var minCost = function(costs) {
    let r = 0, b = 0, g = 0;
    for (const c of costs) {
        const nr = c[0] + Math.min(b, g);
        const nb = c[1] + Math.min(r, g);
        const ng = c[2] + Math.min(r, b);
        r = nr; b = nb; g = ng;
    }
    return Math.min(r, b, g);
};
